import{z as s,x as i,o as e,c as C,q as l,j as r,D as A,d as t,s as n,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"成本与延迟优化","description":"","frontmatter":{"title":"成本与延迟优化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/agent-cost-latency.md","filePath":"llm/agent-cost-latency.md","lastUpdated":1791063341000}'),D={name:"llm/agent-cost-latency.md"};function d(m,E,p,h,c,f){const B=i("Mermaid");return e(),C("div",null,[E[2]||(E[2]=l('<h1 id="成本与延迟优化" tabindex="-1">成本与延迟优化 <a class="header-anchor" href="#成本与延迟优化" aria-label="Permalink to &quot;成本与延迟优化&quot;">​</a></h1><div class="epigraph"><p>代理的花费不与任务难度成正比，与轨迹形状成正比；最贵的杠杆常常最先被拉——降单价，而它恰恰是最慢的一根。</p><footer>—— 据服务成本模型与代理产品的成本口径整理；token 单价见各厂商定价页</footer></div><p><a href="/llm/agent-eval-success-process">上一课</a>把过程指标量了出来，其中步数与 token 成本在本课定价。单次调用的成本工程（<a href="/llm/cost-per-mtok">百万 token 成本</a>、<a href="/llm/serving-cost-model">服务成本模型</a>）已经是常数账；代理的账多了两个变量：步数由模型行为决定，历史由轨迹累积。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>代理成本结构的第一定律是平方律：n 步任务若每步轨迹增长 s 个 token，总输入约为 \\(s \\cdot n(n+1)/2\\)——步数翻倍，总输入近四倍。第二定律是延迟串行：每步要等「模型生成 + 工具执行 + 观察回填」，n 步的墙钟时间是链条求和，没有并行就线性堆。<span class="marginnote">术语翻译：墙钟时间就是「你拿秒表在旁边实测的等待时间」——用户从点击到看到结果的全部秒数，与 CPU 花了多少计算时间是两回事。用户只感知墙钟，所以串行链条再短的一环也是实打实的等待。</span>工程上最容易犯的错是杠杆排序错误：第一步先去谈更便宜的模型单价，而单价是常数因子；轨迹形状是平方因子，砍错方向优化十倍单价也追不上多出的步数。另一个错是把缓存当免费午餐：缓存命中的前提是前缀逐字节稳定（<a href="/llm/prompt-cache">Prompt Cache</a>），而上一课的压缩策略恰恰改前缀——两者不做协调，省下的 token 钱会以缓存全灭的方式还回去。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>杠杆按弹性排序。<strong>砍步数</strong>：更好的计划与更强的工具各抵几步——一次带过滤条件的查询抵五次翻页；规划质量的钱花在这里回报最高。<strong>砍每步上下文</strong>：<a href="/llm/agent-context-strategies">上下文管理策略</a>的折叠与 JIT 句柄直接减小 s。<strong>吃缓存</strong>：系统提示与工具说明放最前并逐字节稳定；可变内容放尾部；<a href="/llm/multi-turn-prefix">多轮前缀命中</a>让第 k 步只需为增量付费。<strong>降单价</strong>：<a href="/llm/model-cascade-routing">模型路由与级联</a>让简单步（格式化、分类、抽取）走小模型，难步走大模型；级联判据要便宜，否则省的钱花在判据上。<span class="marginnote">直觉类比：级联就像医院分诊——感冒发烧去社区门诊（小模型，快且便宜），疑难杂症才转专家门诊（大模型，贵但强）。分诊护士本身要快（判据便宜），否则排队做分诊比直接看病还慢。</span><strong>并行</strong>：独立子任务并行分派（<a href="/llm/agent-multi-orchestration">多 Agent 编排模式</a>的工人并行）、同一轮的多个独立工具调用并行发起、无依赖的预取提前做。延迟侧另有一套：流式输出改善感知延迟（首 token 延迟见 <a href="/llm/ttft">TTFT</a>，逐 token 体验见 <a href="/llm/tpot-itl">交错延迟 TPOT / ITL</a>），工具并行化打断串行链。</p>',7)),(e(),r(o,null,{default:A(()=>[n(B,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20TASK%5B%22%E4%BB%BB%E5%8A%A1%E8%BF%9B%E6%9D%A5%22%5D%20--%3E%20LEV%7B%22%E6%8C%89%E5%BC%B9%E6%80%A7%E6%8B%89%E6%9D%A0%E6%9D%86%22%7D%0A%20%20LEV%20--%3E%7C%22%E7%AC%AC%E4%B8%80%E6%9D%A0%E6%9D%86%22%7C%20STEP%5B%22%E7%A0%8D%E6%AD%A5%E6%95%B0%EF%BC%9A%E8%AE%A1%E5%88%92%E4%B8%8E%E5%B7%A5%E5%85%B7%22%5D%0A%20%20LEV%20--%3E%7C%22%E7%AC%AC%E4%BA%8C%E6%9D%A0%E6%9D%86%22%7C%20CTX%5B%22%E7%A0%8D%E6%AF%8F%E6%AD%A5%E4%B8%8A%E4%B8%8B%E6%96%87%EF%BC%9A%E6%8A%98%E5%8F%A0%E4%B8%8E%E5%8F%A5%E6%9F%84%22%5D%0A%20%20LEV%20--%3E%7C%22%E7%AC%AC%E4%B8%89%E6%9D%A0%E6%9D%86%22%7C%20CACHE%5B%22%E5%90%83%E7%BC%93%E5%AD%98%EF%BC%9A%E5%89%8D%E7%BC%80%E7%A8%B3%E5%AE%9A%E8%AE%BE%E8%AE%A1%22%5D%0A%20%20LEV%20--%3E%7C%22%E7%AC%AC%E5%9B%9B%E6%9D%A0%E6%9D%86%22%7C%20PRICE%5B%22%E9%99%8D%E5%8D%95%E4%BB%B7%EF%BC%9A%E7%BA%A7%E8%81%94%E4%B8%8E%E6%A1%A3%E4%BD%8D%22%5D%0A%20%20LEV%20--%3E%7C%22%E7%AC%AC%E4%BA%94%E6%9D%A0%E6%9D%86%22%7C%20PARA%5B%22%E5%B9%B6%E8%A1%8C%EF%BC%9A%E5%AD%90%E4%BB%BB%E5%8A%A1%E3%80%81%E5%B7%A5%E5%85%B7%E3%80%81%E9%A2%84%E5%8F%96%22%5D%0A%20%20STEP%20--%3E%20ACC%5B%22%E7%B4%AF%E8%AE%A1%E8%BE%93%E5%85%A5%E8%B4%A6%22%5D%0A%20%20CTX%20--%3E%20ACC%0A%20%20CACHE%20--%3E%20ACC%0A%20%20PRICE%20--%3E%20ACC%0A%20%20PARA%20--%3E%20ACC%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"为什么步数杠杆最大：它作用在平方项上。算例：\\(s=2000\\)、\\(n=20\\) 时总输入约 \\(2000 \\times 210 = 42\\) 万 token；步数砍到 10，直接降为 \\(2000 \\times 55 = 11\\) 万，省约 74%——同等努力下降单价或换小模型都拿不到这个比例。缓存与压缩的冲突是同一笔账的分配问题：缓存要求「已发生的不变」，压缩要求「没用的消失」；协调方案是分层摆放加阶段边界压缩（回指上一课），让缓存在阶段内复利、在边界一次性让路。延迟的机制解是打断依赖链：把「必须等上一步结果才能发起」的调用识别出来，其余全部并行或预取；串行链每多一环，尾部延迟就是乘法。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"给成本模型留三列非模型支出：工具与沙箱的执行时长、外部 API 费、人工介入的工资折算。只算 token 的成本表会系统性高估自动化的便宜——长尾任务里人工接管才是最大单项。")],-1)),E[6]||(E[6]=a("p",null,"延迟的机制解是打断依赖链：把「必须等上一步结果才能发起」的调用识别出来，其余全部并行或预取；串行链每多一环，尾部延迟就是乘法。",-1)),(e(),r(o,null,{default:A(()=>[n(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20SER%5B%22%E4%B8%B2%E8%A1%8C%EF%BC%9A%E6%80%BB%E5%BB%B6%E8%BF%9F%20%3D%20%E5%90%84%E7%8E%AF%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20%20%20A1%5B%22%E7%94%9F%E6%88%90%22%5D%20--%3E%20A2%5B%22%E5%B7%A5%E5%85%B7%E6%89%A7%E8%A1%8C%22%5D%20--%3E%20A3%5B%22%E8%A7%82%E5%AF%9F%E5%9B%9E%E5%A1%AB%22%5D%20--%3E%20A4%5B%22%E5%86%8D%E7%94%9F%E6%88%90%22%5D%20--%3E%20A5%5B%22%E5%86%8D%E6%89%A7%E8%A1%8C%22%5D%0A%20%20end%0A%20%20subgraph%20PAR%5B%22%E6%89%93%E6%96%AD%E4%BE%9D%E8%B5%96%E9%93%BE%22%5D%0A%20%20%20%20B0%5B%22%E8%AE%A1%E5%88%92%EF%BC%9A%E8%AF%86%E5%88%AB%E5%93%AA%E4%BA%9B%E8%B0%83%E7%94%A8%E4%BA%92%E4%B8%8D%E4%BE%9D%E8%B5%96%22%5D%20--%3E%20B1%5B%22%E7%8B%AC%E7%AB%8B%E5%B7%A5%E5%85%B7%E5%B9%B6%E8%A1%8C%E5%8F%91%E8%B5%B7%22%5D%0A%20%20%20%20B0%20--%3E%20B2%5B%22%E6%97%A0%E4%BE%9D%E8%B5%96%E7%9A%84%E9%A2%84%E5%8F%96%E6%8F%90%E5%89%8D%E5%81%9A%22%5D%0A%20%20%20%20B0%20--%3E%20B3%5B%22%E7%8B%AC%E7%AB%8B%E5%AD%90%E4%BB%BB%E5%8A%A1%E5%88%86%E7%BB%99%E5%B7%A5%E4%BA%BA%E5%B9%B6%E8%A1%8C%22%5D%0A%20%20%20%20B1%20--%3E%20B4%5B%22%E6%B1%87%E5%90%88%E7%82%B9%EF%BC%9A%E5%8F%AA%E7%AD%89%E6%9C%80%E6%85%A2%E7%9A%84%E4%B8%80%E8%B7%AF%22%5D%0A%20%20%20%20B2%20--%3E%20B4%0A%20%20%20%20B3%20--%3E%20B4%0A%20%20end%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>成本优化有三条不可越的线。恢复预算不能砍：重试上限、验证器、门禁检查是保险费（<a href="/llm/agent-error-recovery">错误恢复与重试</a>），省掉它们把失败成本后移并放大。质量-延迟是帕累托前沿不是免费午餐（<a href="/llm/latency-throughput-pareto">延迟-吞吐帕累托</a>）：每一次降延迟的选择都要问牺牲了哪个分位数。<span class="marginnote">常见误区：初学者容易以为「命中缓存就是白拿钱」。实际上缓存省的是算前缀的钱，前提是前缀一个字节都不能改——哪怕在系统提示末尾加了句日期，从那以后的所有缓存全部作废，账单反而更贵。</span>压缩太狠省的是 token、赔的是任务成功率——回到<a href="/llm/agent-eval-success-process">评测：任务成功率与过程</a>把「省钱后成功率」测出来，成本优化才有验收标准。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>平方律先于单价：\\(n\\) 步、每步 \\(s\\) token，总输入 \\(\\approx s \\cdot n^2/2\\)；步数是第一杠杆。</li><li>杠杆顺序：砍步数、砍上下文、吃缓存、降单价、并行；单价是常数因子。</li><li>缓存与压缩协调：稳定段吃缓存复利，压缩只在阶段边界发生。</li><li>延迟优化=打断串行依赖链；感知延迟用流式补。</li><li>成本表要含工具、外部 API 与人工接管，不只算 token。</li><li>出处：成本口径据各家定价与服务成本模型整理；机制结论为本课程各课汇总。</li></ul>',4))])}const F=s(D,[["render",d]]);export{u as __pageData,F as default};
